export interface Repo {
  find(id: number): string | undefined;
  save(id: number, row: string): void;
}
// MemoryRepo claims to implement Repo but is missing save.
export class MemoryRepo implements Repo {
  #rows = new Map<number, string>();
  find(id: number): string | undefined { return this.#rows.get(id); }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { MemoryRepo } from '../src/repo.ts';
test('save then find', () => { const r = new MemoryRepo(); r.save(1, 'BE-201'); assert.equal(r.find(1), 'BE-201'); });

